import 'package:flutter/material.dart';
import 'dart:async';
import 'package:file_share_intent/file_share_intent.dart';

void main() => runApp(MyApp());

class MyApp extends StatefulWidget {
  @override
  _MyAppState createState() => _MyAppState();
}

class _MyAppState extends State<MyApp> {
  late StreamSubscription _intentSub;
  final _sharedFiles = <SharedMediaFile>[];

  @override
  void initState() {
    super.initState();
    _intentSub = FileShareIntent.instance.getMediaStream().listen((value) {
      setState(() {
        _sharedFiles.clear();
        _sharedFiles.addAll(value);
      });
    });
  }

  @override
  Widget build(BuildContext context) => MaterialApp(home: Scaffold(body: Center(child: Text('Shared files: ${_sharedFiles.length}'))));
}
